 identification:{title:'Ficha clínica ampliada',description:'Datos pertinentes para contextualizar la atención y adaptar el seguimiento.',kind:'single',fields:[['sex_at_birth','Sexo registrado al nacimiento','select',['No evaluado','Femenino','Masculino','Intersexual','Prefiere no informar']],['occupation','Ocupación','text'],['work_schedule','Jornada y horarios','text'],['locality','Localidad o zona','text'],['civil_status','Estado civil, si es pertinente','text'],['health_service','Servicio de salud o profesional tratante','text'],['contact_preference','Preferencia de comunicación','text'],['emergency_contact','Contacto de emergencia opcional','text']]},
 family:{title:'Antecedentes heredofamiliares',description:'Una condición por registro, con parentesco y procedencia.',kind:'rows',fields:[['condition','Condición','text'],['relation','Parentesco','text'],['lineage','Línea familiar','select',['No especificada','Materna','Paterna','Ambas']],['onset_age','Edad aproximada de presentación','text'],['status','Estado','select',['Referido','Documentado','Negado','Desconocido']],['source','Fuente','text']]},
