 surgeries:{title:'Cirugías y hospitalizaciones',description:'Episodios clínicos relevantes con fecha exacta o aproximada.',kind:'rows',fields:[['type','Tipo','text'],['reason','Motivo','text'],['date','Fecha o periodo','text'],['complications','Complicaciones referidas','text'],['source','Fuente','text']]},
 allergies:{title:'Alergias e intolerancias',description:'Separa alergia, intolerancia, sospecha y preferencia.',kind:'rows',fields:[['substance','Alimento o sustancia','text'],['classification','Clasificación','select',['Alergia confirmada','Alergia referida','Intolerancia confirmada','Intolerancia referida','Sospecha','Preferencia o rechazo']],['reaction','Reacción o manifestación','text'],['severity','Gravedad referida','text'],['date','Fecha o periodo','text'],['source','Fuente','text']]},
 digestive:{title:'Evaluación digestiva',description:'Síntomas, temporalidad, relación alimentaria y señales que requieren revisión.',kind:'rows',fields:[['symptom','Síntoma','select',['Náusea','Vómito','Diarrea','Estreñimiento','Distensión','Reflujo','Disfagia','Dolor abdominal','Otro']],['status','Estado','select',['Presente','Ausente','Desconocido','No evaluado']],['onset','Inicio','text'],['frequency','Frecuencia y duración','text'],['intensity','Intensidad y escala','text'],['food_relation','Relación temporal con alimentos','text'],['alarm_signs','Signos de alarma referidos','text'],['source','Fuente','text']]},
 sleep:{title:'Sueño y descanso',description:'Patrón referido correspondiente al periodo evaluado.',kind:'single',fields:[['bedtime','Hora habitual de dormir','time'],['wake_time','Hora habitual de despertar','time'],['hours','Horas aproximadas','number'],['latency','Latencia y despertares','text'],['naps','Siestas','text'],['quality','Calidad referida','select',['No evaluada','Muy buena','Buena','Regular','Mala','Muy mala']],['period','Periodo evaluado','text'],['source','Fuente','text']]},
 activity:{title:'Actividad física y sedentarismo',description:'Una actividad por registro; no asigna automáticamente un factor energético.',kind:'rows',fields:[['activity','Actividad','text'],['frequency','Sesiones por semana','number'],['duration','Minutos por sesión','number'],['intensity','Intensidad y método','text'],['limitations','Limitaciones o síntomas','text'],['sedentary_time','Tiempo sedentario referido','text'],['source','Fuente','text']]},
