 hormonal:{title:'Historia ginecológica hormonal y menopausia',description:'Módulo condicional. No clasifica una etapa automáticamente.',kind:'single',fields:[['applicability','Aplicabilidad','select',['No evaluada','Aplica','No aplica','Prefiere no informar']],['last_menstrual_period','Última menstruación','date'],['cycle_regularity','Regularidad','select',['No evaluada','Regular referida','Irregular referida','Sin menstruación']],['cycle_length','Duración del ciclo y sangrado','text'],['bleeding','Características del sangrado','text'],['symptoms','Síntomas asociados','textarea'],['amenorrhea_duration','Duración de amenorrea','text'],['stage','Etapa referida o documentada','select',['No evaluada','Transición menopáusica referida','Menopausia referida','Posmenopausia referida','Documentada por otro profesional']],['stage_basis','Fundamento y fuente de etapa','text'],['pregnancy_lactation','Embarazo o lactancia actual','text'],['obstetric_history','Antecedentes obstétricos pertinentes','textarea'],['gynecologic_conditions','Condiciones ginecológicas documentadas','textarea'],['hormonal_therapy','Terapia hormonal y prescriptor','textarea'],['source','Fuente general','text']]},
 signs:{title:'Signos clínicos observados',description:'Registra observaciones objetivas; no convierte un signo aislado en diagnóstico.',kind:'rows',fields:[['sign','Signo o área','select',['Piel','Ojos','Uñas','Cabello','Boca','Dentición','Acantosis','Acné','Edema','Hiperandrogenismo','Otro']],['status','Estado','select',['Sin alteración observada','Alterado','No evaluado','No aplicable']],['description','Descripción objetiva','text'],['location','Localización y lateralidad','text'],['action','Acción o referencia','text'],['source','Profesional y fuente','text']]},
 dietary_context:{title:'Contexto alimentario',description:'Factores prácticos que condicionan la evaluación y el plan.',kind:'single',fields:[['prior_guidance','Orientación o planes previos','textarea'],['recent_changes','Cambios recientes y motivo','textarea'],['preferences','Preferencias','textarea'],['rejected_foods','Alimentos rechazados','textarea'],['water_beverages','Agua y otras bebidas por periodo','textarea'],['shopping_cooking','Quién compra y prepara','text'],['budget_household','Presupuesto y número de comensales','text'],['resources','Tiempo, refrigeración y equipo','textarea'],['source','Fuente','text']]},
 intake:{title:'Recordatorio de 24 horas y patrón habitual',description:'Cada evento identifica método, fecha, horario, lugar, cantidades y preparación.',kind:'rows',fields:[['method','Método','select',['Recordatorio de 24 horas','Patrón habitual entre semana','Patrón habitual fin de semana','Registro alimentario']],['reference_date','Fecha o periodo','text'],['typicality','Tipo de día','select',['Habitual','Atípico','No determinado']],['meal','Tiempo o evento','text'],['time','Hora','time'],['place','Lugar','text'],['foods','Alimentos bebidas y marcas','textarea'],['quantity','Cantidad y medida casera','text'],['preparation','Preparación y estado crudo o cocido','text'],['symptoms','Hambre saciedad o síntomas posteriores','text'],['source','Fuente','text']]},
